import * as THREE from 'three';
import {buildForceDiagram} from './force-data.js';
import {boatScale} from './boats.js';
import {getLanguage} from './i18n.js';
export class ForceView{
 constructor(owner){this.owner=owner;this.group=new THREE.Group();this.group.name='educational-force-vectors';owner.scene.add(this.group);this.objects=new Map();this.labels=new Map();}
 clear(){for(const object of this.objects.values()){this.group.remove(object);object.traverse(o=>{o.geometry?.dispose();if(Array.isArray(o.material))o.material.forEach(m=>m.dispose());else o.material?.dispose();});}for(const label of this.labels.values())label.remove();this.objects.clear();this.labels.clear();}
 pickAt(clientX,clientY,touch=false){if(!this.group.visible)return null;const o=this.owner,r=o.canvas.getBoundingClientRect();if(!r.width||!r.height)return null;const threshold=touch?22:11,candidates=[];o.scene.updateMatrixWorld(true);o.camera.updateMatrixWorld(true);for(const [id,object]of this.objects){if(!object.visible)continue;const p=object.getWorldPosition(new THREE.Vector3()).project(o.camera);if(p.z< -1||p.z>1)continue;const distance=Math.hypot((p.x*.5+.5)*r.width+r.left-clientX,(-p.y*.5+.5)*r.height+r.top-clientY);if(distance<threshold)candidates.push({id,distance});}if(candidates.length)return candidates.sort((a,b)=>a.distance-b.distance)[0].id;const ray=new THREE.Raycaster();ray.params.Line.threshold=2*o.camera.position.distanceTo(o.controls?.target||new THREE.Vector3())*Math.tan(o.camera.fov*Math.PI/360)*(touch?10:5)/r.height;ray.setFromCamera(new THREE.Vector2((clientX-r.left)/r.width*2-1,1-(clientY-r.top)/r.height*2),o.camera);for(const hit of ray.intersectObjects([...this.objects.values()].filter(x=>x.visible),true)){let obj=hit.object;while(obj&&!obj.userData.forceItem)obj=obj.parent;if(obj?.userData.forceItem)return obj.userData.forceItem.id;}return null;}
 setHover(id){this.hover=id;}
 toggleLabel(id){const s=this.owner.getState();s.forceFocus=s.forceFocus===id?null:id;this.hover=null;}
 update(s,m){this.group.visible=!!s.forces;if(!s.forces){for(const label of this.labels.values())label.hidden=true;return;}const config=JSON.stringify([s.forceGroups,s.forceFocus,s.forceScale,getLanguage()]),rebuild=this.metric!==m||this.config!==config;if(rebuild){this.metric=m;const structure=JSON.stringify([s.forceGroups,getLanguage()]);if(this.structure!==structure)this.clear();this.structure=structure;this.config=config;for(const object of this.objects.values())object.visible=false;for(const label of this.labels.values())label.hidden=true;this.data=buildForceDiagram(s,m);const k=boatScale(s);for(const item of this.data.items){if(s.forceGroups?.[item.group]===false||item.magnitude<.05&&item.kind!=='centre')continue;let object=this.objects.get(item.id);if(!object&&item.kind==='centre'){object=new THREE.Mesh(new THREE.SphereGeometry(.085*k,12,8),new THREE.MeshBasicMaterial({color:item.color,depthTest:false,transparent:true}));object.renderOrder=19;}else if(!object&&item.kind==='moment'){const radius=(1.2+Math.min(1.5,Math.log10(1+item.magnitude/500)))*k,points=[];for(let i=0;i<=40;i++){const angle=i/40*Math.PI*1.5*(Math.sign(item.value)||1),p=item.axis[1]?[Math.cos(angle)*radius,0,Math.sin(angle)*radius]:[Math.cos(angle)*radius,Math.sin(angle)*radius,0];points.push(new THREE.Vector3(...p));}object=new THREE.Group();const line=new THREE.Line(new THREE.BufferGeometry().setFromPoints(points),new THREE.LineBasicMaterial({color:item.color,depthTest:false,transparent:true,opacity:.8}));object.add(line);const head=new THREE.Mesh(new THREE.ConeGeometry(.12*k,.32*k,12),new THREE.MeshBasicMaterial({color:item.color,depthTest:false,transparent:true}));head.position.copy(points.at(-1));head.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),points.at(-1).clone().sub(points.at(-2)).normalize());object.add(head);object.renderOrder=18;}else if(!object){const length=Math.min(7,.55+1.45*Math.log10(1+item.magnitude/100))*k*(s.forceScale||1);object=new THREE.ArrowHelper(new THREE.Vector3(0,1,0),new THREE.Vector3(),length,item.color,Math.min(.38*k,length*.25),.15*k);object.line.material.depthTest=false;object.line.material.transparent=true;object.cone.material.depthTest=false;object.cone.material.transparent=true;object.renderOrder=18;}if(item.kind==='force'){const length=Math.min(7,.55+1.45*Math.log10(1+item.magnitude/100))*k*(s.forceScale||1);object.setLength(length,Math.min(.38*k,length*.25),.15*k);}object.visible=true;object.userData.forceItem=item;this.group.add(object);this.objects.set(item.id,object);{let label=this.labels.get(item.id);if(!label)label=document.createElement('div');label.className='force-label'+(item.estimated?' is-estimated':'');label.style.setProperty('--force-color',item.color);label.dataset.forceId=item.id;label.textContent=(getLanguage()==='en'?item.en:item.label)+(item.kind==='centre'?'':` · ${item.magnitude.toLocaleString(getLanguage()==='en'?'en-GB':'it-IT',{maximumFractionDigits:0})} ${item.unit}`);this.owner.canvas.parentElement.appendChild(label);this.labels.set(item.id,label);}}}
  const {boat,camera,width,height}=this.owner;boat.updateMatrixWorld(true);const rotation=new THREE.Quaternion();boat.getWorldQuaternion(rotation);const occupied=[];
  for(const [id,object]of this.objects){if(!object.visible)continue;const item=object.userData.forceItem,position=boat.localToWorld(new THREE.Vector3(...item.origin.map(v=>v/boatScale(s))));object.position.copy(position);if(item.kind==='force'){const direction=new THREE.Vector3(...item.vector).normalize();if(!item.worldDirection)direction.applyQuaternion(rotation);object.setDirection(direction);}else if(item.kind==='moment')object.quaternion.copy(rotation);const selected=!s.forceFocus||s.forceFocus===id||this.hover===id;object.traverse(o=>{if(o.material){o.material.transparent=true;o.material.opacity=selected?1:.16;}});const label=this.labels.get(id);if(label){label.hidden=id!==this.hover&&id!==s.forceFocus;if(label.hidden)continue;const screen=position.clone().project(camera);if(screen.z>1||screen.x< -1.1||screen.x>1.1||screen.y< -1.1||screen.y>1.1){label.hidden=true;continue;}let x=(screen.x*.5+.5)*width+12,y=(-screen.y*.5+.5)*height-12;const w=Math.min(230,label.offsetWidth||190);x=Math.min(width-w-8,Math.max(8,x));for(let n=0;n<8&&occupied.some(r=>Math.abs(y-r.y)<25&&x<r.x+r.w&&x+w>r.x);n++)y+=25;y=Math.min(height-26,Math.max(8,y));occupied.push({x,y,w});label.style.left=x+'px';label.style.top=y+'px';label.hidden=false;}}
 }
}
